#!/bin/bash
# run_tests.sh
# Purpose: Runs the Section 10 tests against the compiled program and writes
#          test_results.txt from the program's real output.
# Author:  Sushil Gautam, Anish Dahal, Vijay Ram Sanvi Bhaskarla
#
# Run from the project root:
#   g++ -std=c++11 -Iinclude src/*.cpp -o campus
#   bash testdata/run_tests.sh
# Or, for the Final menu and every test:
#   g++ -std=c++11 -Iinclude -DFINAL_MENU src/*.cpp -o campus
#   MODE=final bash testdata/run_tests.sh
#
# Test inputs below are written with the Final menu numbers. In the default
# m1 mode, Final-only tests are skipped and menu numbers are translated to the
# Milestone 1 numbering.

CAMPUS=${CAMPUS:-./campus}
MODE=${MODE:-m1}
if [ "$MODE" = final ]; then
    MENU_ERROR="Error: enter a number from 0 to 17."
else
    MENU_ERROR="Error: enter a number from 0 to 9."
fi
RESULTS=test_results.txt
OUTPUT_DIR=testdata/.output
mkdir -p "$OUTPUT_DIR"

number=0
passed=0
failed=0

# Lists the keyboard entries of an input script in quotes, so that a blank
# entry shows as "".
show_entries() {
    local rest=$1 result="" token
    while [ -n "$rest" ]; do
        token=${rest%%\\n*}
        rest=${rest#*\\n}
        result+="${result:+, }\"$token\""
    done
    printf '%s' "$result"
}

# Checks that each expected text appears in the output, in the given order.
# A text starting with ! must not appear anywhere in the output.
# Usage: run_program TAG DESCRIPTION DATA_DIR STDIN EXPECTED...
run_program() {
    local tag=$1 description=$2 directory=$3 input=$4
    shift 4
    number=$((number + 1))
    local output="$OUTPUT_DIR/test_$number.txt"
    printf '%b' "$input" | "$CAMPUS" "$directory" 2>&1 | tr -d '\r' > "$output"
    local status=${PIPESTATUS[1]}

    local result=PASS actual="" position=1 expected line found
    for expected in "$@"; do
        if [ "${expected:0:1}" = "!" ]; then
            if grep -qF -- "${expected:1}" "$output"; then
                result=FAIL
                actual+="    UNEXPECTED: ${expected:1}"$'\n'
            else
                actual+="    (absent, as required): ${expected:1}"$'\n'
            fi
            continue
        fi
        found=$(tail -n +"$position" "$output" | grep -nF -m1 -- "$expected")
        if [ -z "$found" ]; then
            result=FAIL
            actual+="    MISSING: $expected"$'\n'
        else
            line=${found%%:*}
            actual+="    ${found#*:}"$'\n'
            position=$((position + line))
        fi
    done
    if [ "$status" -ne 0 ]; then
        result=FAIL
        actual+="    Program exit status: $status"$'\n'
    fi

    {
        echo "Test $number [$tag]: $description"
        echo "  Input: data directory $directory; keyboard entries: $(show_entries "$input")"
        echo "  Expected:"
        printf '    %s\n' "$@"
        echo "  Actual:"
        printf '%s' "$actual"
        echo "  Result: $result"
        echo
    } >> "$RESULTS"

    if [ "$result" = PASS ]; then
        passed=$((passed + 1))
    else
        failed=$((failed + 1))
        echo "FAIL: test $number: $description"
    fi
}

# Converts Final menu numbers in an input script to Milestone 1 numbers. Only
# whole lines are converted, so IDs and names are left alone.
to_m1_numbers() {
    local rest=$1 result="" token
    while [ -n "$rest" ]; do
        token=${rest%%\\n*}
        rest=${rest#*\\n}
        case "$token" in
            5) token=3 ;;
            6) token=4 ;;
            7) token=5 ;;
            9) token=6 ;;
            10) token=7 ;;
            11) token=8 ;;
            12) token=9 ;;
        esac
        result+="$token\\n"
    done
    printf '%s' "$result"
}

# Runs a test written with Final menu numbers, for the current mode.
t() {
    local tag=$1 description=$2 directory=$3 input=$4
    shift 4
    if [ "$MODE" = final ]; then
        run_program "$tag" "$description" "$directory" "$input" "$@"
    elif [ "$tag" = M1 ]; then
        run_program "$tag" "$description" "$directory" "$(to_m1_numbers "$input")" "$@"
    fi
}

{
    echo "Smart Campus Navigation and Facility Analytics System: Test Results"
    echo "Generated by testdata/run_tests.sh on $(date '+%Y-%m-%d')"
    echo "Platform: $(uname -sm); compiler: $(g++ --version | head -1)"
    echo "Menu tested: $MODE. Keyboard input uses that menu's numbering."
    echo "Tag shows the phase that requires the test. Expected texts are"
    echo "checked in order; Actual shows the program's matching output lines."
    echo
} > "$RESULTS"

