# ---- Memory check (NFR-11), when Valgrind is installed ----
{
    echo "Memory check:"
    if command -v valgrind > /dev/null; then
        if [ "$MODE" = final ]; then
            script='9\nData Science\nUniversity\n8\nLibrary\nGym\n13\n14\n15\n16\n17\n0\n'
        else
            script='6\nData Science\nUniversity\n5\nLibrary\n8\n9\n0\n'
        fi
        printf '%b' "$script" |
            valgrind --leak-check=full "$CAMPUS" data 2>&1 > /dev/null |
            grep -E 'in use at exit|All heap blocks|definitely lost|ERROR SUMMARY'
    else
        echo "  Valgrind is not installed on this machine; no memory check was run."
    fi
    echo
    echo "Summary: $passed passed, $failed failed, $number total"
} >> "$RESULTS"
echo "Summary: $passed passed, $failed failed, $number total"
